def getMaxMinWeight(weights, k):
    n = len(weights)

    if n <= k:
        return max(weights)

    weights.sort(reverse=True)

    low = weights[0]
    high = sum(weights)

    while low < high:
        mid = (low + high) // 2
        buckets = [0] * k

        if check(0, weights, buckets, mid):
            high = mid
        else:
            low = mid + 1

    return low


